def bfs(s):
    q = deque([s])
    visited = {s}
    while q:
        s = q.popleft()
        for i in range(4):
            t = s[:]
            x, y = divmod(t.index('X')), 2)
            dx, dy = [0, 1, 0, -1], [-1, 0, 1, 0]
            nx, ny = x + dx[i], y + dy[i]
            if 0 <= nx < 2 and 0 <= ny < 2:
                t[t.index('X')]] = t[nx * 2 + ny]]
                t[nx * 2 + ny]] = 'X'
                if ''.join(t) == 'ABCX':
                    return True
                elif ''.join(t) not in visited:
                    visited.add(''.join(t))
                    q.append(t)
    return False


