def get_area(ns,es):
    def get_x(c):
        return c[0] + c[2]

    def get_y(c):
        return c[1] + c[2]

    def get_line(c):
        return (get_x(c),get_y(c)),(get_x(c)+1,get_y(c)+1))

    def get_intersect(l1,l2):
        x1,y1 = l1[0]
        x2,y2 = l1[1]
        x3,y3 = l2[0]
        x4,y4 = l2[1]
        det = (x1-x2)*(y3-y4)-(y1-y2)*(x3-x4))
        if det == 0:
            return None
        else:
            x = ((x1*x2+y1*y2)*(-x3+x4)+(x1*x3+y1*y3)*(-x2+x4)+(x1*x4+y1*y4)*(-x2+x3)))/det
            y = ((y1*y2+x1*x2)*(-y3+y4)+(y1*y3+x1*x3)*(-y2+y4)+(y1*y4+x1*x4)*(-y2+y3)))/det
            return (x,y)

    def get_polygon(ns):
        p = []
        for n in ns:
            p.append(get_line(n)))
        return p

    def get_area_of_polygon(p):
        area = 0
        for i in range(len(p))):
            x1,y1 = p[i][0]
            x2,y2 = p[i][1]
            area += (x1+x2)*(y1+y2))
        return abs(area)//2

    p = get_polygon(ns)
    area = get_area_of_polygon(p)
    return area

